export function AlertDialog({
  title = "{{title}}",
  message = "{{message}}",
  tone = "{{tone}}",
  accent = "{{accent}}",
  width = {{width}},
  backdrop = {{backdrop}},
}) {
  const stripe = { info: "#BFD9F2", warning: "#E8A020", danger: "#F5C2E0" }[tone] ?? accent;
  return (
    <div style={{ position: "relative", minHeight: 420, display: "grid", placeItems: "center",
      borderRadius: 12, background: "linear-gradient(135deg, #BFD9F2, #D9C8F0)" }}>
      {backdrop && <div style={{ position: "absolute", inset: 0, background: "rgba(36,20,48,.45)" }} />}
      <div role="alertdialog" aria-modal="true" aria-labelledby="ad-title" style={{ position: "relative",
        zIndex: 1, width, boxSizing: "border-box", background: "#FAF7F2", color: "#241430", borderRadius: 14,
        borderTop: "6px solid " + stripe, boxShadow: "0 20px 44px rgba(36,20,48,.28)", padding: 24, textAlign: "center" }}>
        <div aria-hidden="true" style={{ width: 40, height: 40, margin: "0 auto 12px", borderRadius: "50%",
          display: "grid", placeItems: "center", fontWeight: 700, fontSize: 18, background: "#24143012" }}>!</div>
        <h3 id="ad-title" style={{ margin: "0 0 8px", fontSize: 18, fontWeight: 600 }}>{title}</h3>
        <p style={{ margin: "0 0 20px", fontSize: 14, color: "#241430cc" }}>{message}</p>
        <div style={{ display: "flex", justifyContent: "center" }}>
          <button type="button" style={{ background: accent, borderColor: accent, color: "#FAF7F2" }}>OK</button>
        </div>
      </div>
    </div>
  );
}
